import { Document, Page, Text, View, StyleSheet } from '@react-pdf/renderer';
import type { Document as StoreDocument, Party } from '@/lib/platformStore';

/**
 * InvoicePdf — a real, downloadable PDF generated by @react-pdf/renderer.
 * Renders the invoice document as a print-ready PDF: header, party block,
 * line items table, totals, footer. Matches the on-screen Edit view.
 *
 * Used by DocumentEngine.downloadPdf() — the "PDF" footer button.
 */

const styles = StyleSheet.create({
  page: { padding: 48, fontSize: 11, fontFamily: 'Helvetica', color: '#1a1c1e' },
  header: { flexDirection: 'row', justifyContent: 'space-between', marginBottom: 32, paddingBottom: 16, borderBottomWidth: 2, borderBottomColor: '#1e6dc9' },
  docType: { fontSize: 24, fontWeight: 'bold', color: '#1e6dc9' },
  docNumber: { fontSize: 12, color: '#5a6355', marginTop: 4 },
  totalLabel: { fontSize: 10, color: '#5a6355', textTransform: 'uppercase' },
  totalAmount: { fontSize: 24, fontWeight: 'bold', marginTop: 2 },
  parties: { flexDirection: 'row', justifyContent: 'space-between', marginBottom: 32 },
  partyBlock: { flex: 1 },
  partyLabel: { fontSize: 9, color: '#5a6355', textTransform: 'uppercase', marginBottom: 4 },
  partyName: { fontSize: 13, fontWeight: 'bold', marginBottom: 2 },
  partyLine: { fontSize: 10, color: '#5a6355' },
  dates: { flex: 1, alignItems: 'flex-end' },
  dateLabel: { fontSize: 9, color: '#5a6355', textTransform: 'uppercase', marginBottom: 2 },
  dateValue: { fontSize: 11, marginBottom: 8 },
  tableHeader: { flexDirection: 'row', borderBottomWidth: 1, borderBottomColor: '#dad9dd', paddingBottom: 6, marginBottom: 4 },
  tableHeaderCell: { fontSize: 9, fontWeight: 'bold', color: '#5a6355', textTransform: 'uppercase' },
  row: { flexDirection: 'row', paddingVertical: 6, borderBottomWidth: 1, borderBottomColor: '#f0eef0' },
  cellDesc: { flex: 3, fontSize: 10 },
  cellNum: { flex: 1, fontSize: 10, textAlign: 'right' },
  totals: { marginTop: 24, alignSelf: 'flex-end', width: 200 },
  totalRow: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: 2 },
  totalRowBold: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: 6, borderTopWidth: 1, borderTopColor: '#dad9dd', marginTop: 4 },
  totalRowText: { fontSize: 11 },
  totalRowBoldText: { fontSize: 14, fontWeight: 'bold' },
  footer: { position: 'absolute', bottom: 48, left: 48, right: 48, fontSize: 9, color: '#9aa0a6', textAlign: 'center', borderTopWidth: 1, borderTopColor: '#f0eef0', paddingTop: 12 },
});

export function InvoicePdf({ doc, party }: { doc: StoreDocument; party: Party | null }) {
  const customerName = party?.name || party?.displayName || 'Customer';
  const customerAddress = [party?.address, party?.city, party?.state, party?.zip].filter(Boolean).join(', ');
  const docTypeLabel = doc.type === 'Invoice' ? 'INVOICE'
    : doc.type === 'Estimate' ? 'ESTIMATE'
    : doc.type === 'SalesReceipt' ? 'SALES RECEIPT'
    : doc.type === 'CreditMemo' ? 'CREDIT MEMO'
    : doc.type === 'Bill' ? 'BILL'
    : doc.type === 'PurchaseOrder' ? 'PURCHASE ORDER'
    : doc.type.toUpperCase();

  return (
    <Document>
      <Page size="LETTER" style={styles.page}>
        {/* Header */}
        <View style={styles.header}>
          <View>
            <Text style={styles.docType}>{docTypeLabel}</Text>
            <Text style={styles.docNumber}>{doc.number}</Text>
          </View>
          <View style={{ alignItems: 'flex-end' }}>
            <Text style={styles.totalLabel}>{docTypeLabel} Total</Text>
            <Text style={styles.totalAmount}>${doc.total.toFixed(2)}</Text>
          </View>
        </View>

        {/* Parties + dates */}
        <View style={styles.parties}>
          <View style={styles.partyBlock}>
            <Text style={styles.partyLabel}>Bill To</Text>
            <Text style={styles.partyName}>{customerName}</Text>
            {party?.email ? <Text style={styles.partyLine}>{party.email}</Text> : null}
            {party?.phone ? <Text style={styles.partyLine}>{party.phone}</Text> : null}
            {customerAddress ? <Text style={styles.partyLine}>{customerAddress}</Text> : null}
          </View>
          <View style={styles.dates}>
            <Text style={styles.dateLabel}>{doc.type === 'Estimate' ? 'Estimate Date' : doc.type === 'Bill' ? 'Bill Date' : 'Invoice Date'}</Text>
            <Text style={styles.dateValue}>{doc.date}</Text>
            {doc.dueDate ? (
              <>
                <Text style={styles.dateLabel}>{doc.type === 'Estimate' ? 'Expires' : 'Due Date'}</Text>
                <Text style={styles.dateValue}>{doc.dueDate}</Text>
              </>
            ) : null}
          </View>
        </View>

        {/* Line items */}
        <View style={styles.tableHeader}>
          <Text style={[styles.tableHeaderCell, { flex: 3 }]}>Description</Text>
          <Text style={[styles.tableHeaderCell, { flex: 1, textAlign: 'right' }]}>Qty</Text>
          <Text style={[styles.tableHeaderCell, { flex: 1, textAlign: 'right' }]}>Rate</Text>
          <Text style={[styles.tableHeaderCell, { flex: 1, textAlign: 'right' }]}>Amount</Text>
        </View>
        {doc.lines.map((line) => (
          <View key={line.id} style={styles.row}>
            <Text style={styles.cellDesc}>{line.description || '—'}</Text>
            <Text style={styles.cellNum}>{line.qty}</Text>
            <Text style={styles.cellNum}>${line.rate.toFixed(2)}</Text>
            <Text style={styles.cellNum}>${line.amount.toFixed(2)}</Text>
          </View>
        ))}

        {/* Totals */}
        <View style={styles.totals}>
          <View style={styles.totalRow}>
            <Text style={styles.totalRowText}>Subtotal</Text>
            <Text style={styles.totalRowText}>${doc.subtotal.toFixed(2)}</Text>
          </View>
          {doc.tax > 0 ? (
            <View style={styles.totalRow}>
              <Text style={styles.totalRowText}>Tax</Text>
              <Text style={styles.totalRowText}>${doc.tax.toFixed(2)}</Text>
            </View>
          ) : null}
          {doc.shipping > 0 ? (
            <View style={styles.totalRow}>
              <Text style={styles.totalRowText}>Shipping</Text>
              <Text style={styles.totalRowText}>${doc.shipping.toFixed(2)}</Text>
            </View>
          ) : null}
          <View style={styles.totalRowBold}>
            <Text style={styles.totalRowBoldText}>Total</Text>
            <Text style={styles.totalRowBoldText}>${doc.total.toFixed(2)}</Text>
          </View>
          {doc.amountPaid > 0 ? (
            <View style={styles.totalRow}>
              <Text style={styles.totalRowText}>Paid</Text>
              <Text style={styles.totalRowText}>-${doc.amountPaid.toFixed(2)}</Text>
            </View>
          ) : null}
          {doc.balance > 0 ? (
            <View style={styles.totalRowBold}>
              <Text style={styles.totalRowBoldText}>Balance Due</Text>
              <Text style={styles.totalRowBoldText}>${doc.balance.toFixed(2)}</Text>
            </View>
          ) : null}
        </View>

        {/* Footer */}
        <View style={styles.footer}>
          <Text>{doc.notes || 'Thank you for your business.'}</Text>
        </View>
      </Page>
    </Document>
  );
}

export default InvoicePdf;
